import{_ as n,a as o}from"./chunks/sk_2.CVv6rsse.js";import{_ as d,c as s,o as a,ae as t}from"./chunks/framework.Cd-3tpCq.js";const k=JSON.parse('{"title":"Understanding soundkey","description":"MinecraftSounds Advanced Tutorial - Understanding soundkey","frontmatter":{"title":"Understanding soundkey","description":"MinecraftSounds Advanced Tutorial - Understanding soundkey"},"headers":[],"relativePath":"en/tutorials/soundkey.md","filePath":"en/tutorials/soundkey.md"}'),u={name:"en/tutorials/soundkey.md"};function r(i,e,c,l,y,f){return a(),s("div",null,e[0]||(e[0]=[t('<h1 id="understanding-soundkey" tabindex="-1">Understanding soundkey <a class="header-anchor" href="#understanding-soundkey" aria-label="Permalink to &quot;Understanding soundkey&quot;">​</a></h1><p>In MinecraftSounds, each sound effect has a unique identifier called a soundkey. A soundkey is a string used to reference and play sound effects in the game.</p><p>A soundkey consists of two parts:</p><ol><li>Main key: In step 3 of <a href="./getting-started.html#create-a-new-project">creating a new project</a>, you need to fill in a main key, which will be part of the soundkey.<br><img src="'+n+'" alt="soundkey"></li><li>Sound effect soundkey: In step 2 of <a href="./getting-started.html#adding-sound-effects">adding sound effects</a>, the audio you add will automatically generate a soundkey<br><img src="'+o+'" alt="soundkey"></li></ol><p>The combination of the &quot;main key&quot; and the &quot;sound effect soundkey&quot; forms a complete soundkey.</p><p>For example, a main key named &quot;mcsd&quot; and a sound effect soundkey named &quot;my_sound&quot; would result in a soundkey of &quot;mcsd.my_sound&quot;.</p><h1 id="using-sound-effect-soundkeys" tabindex="-1">Using sound effect soundkeys <a class="header-anchor" href="#using-sound-effect-soundkeys" aria-label="Permalink to &quot;Using sound effect soundkeys&quot;">​</a></h1><p>In MinecraftSounds, you can use sound effect soundkeys to reference and play sound effects.</p><p>For version 1.7.10 and below:<br><code>/playsound {soundkey} @a ~ ~ ~ 10000</code><br> For version 1.8 and above:<br><code>/playsound {soundkey} record @a ~ ~ ~ 10000</code></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>When using a soundkey, you need to replace {soundkey} with the actual soundkey.<br> For example: A main key named &quot;mcsd&quot; and a sound effect soundkey named &quot;my_sound&quot; would result in a soundkey of &quot;mcsd.my_sound&quot;.</p><p>For version 1.7.10 and below:<br><code>/playsound mcsd.my_sound @a ~ ~ ~ 10000</code><br> For version 1.8 and above:<br><code>/playsound mcsd.my_sound record @a ~ ~ ~ 10000</code></p></div>',10)]))}const _=d(u,[["render",r]]);export{k as __pageData,_ as default};
